import {adaptCharacterRig} from '../character-rig-adapter.js';
import * as T from 'three';
import {armCurveWeight,footWeight} from '../dormi-sports-pose.js';
import {createRigidArmMapper} from '../dormi-rigid-arms.js';
import {CURLING_AID as A} from './curling-layout.js';
/** The original arm and rigid delivery aid have fixed dimensions throughout. */
export function createCurlingRig({model,poser}){
 if(poser?.poseReference)return adaptCharacterRig(poser,(model,poser)=>createCurlingRig({model,poser}));
 if(!model?.isObject3D||!poser?.getState||!poser?.setPose)throw TypeError('Original curling actor required');
 const pose=poser.getState(),saved=[],records=[],palms=[],soles={left:[],right:[]},arms=createRigidArmMapper(),v=new T.Vector3(),source=new T.Vector3(),feet={};let alive=true;
 model.traverse(mesh=>{if(mesh.isMesh)saved.push({mesh,g:mesh.geometry,p:mesh.geometry.attributes.position.array.slice(),n:mesh.geometry.attributes.normal?.array.slice(),box:mesh.geometry.boundingBox?.clone(),sphere:mesh.geometry.boundingSphere?.clone()});});
 function restore(){poser.setPose(pose.name,pose.amount,pose.time);for(const r of saved){r.mesh.geometry=r.g;r.g.attributes.position.array.set(r.p);r.g.attributes.position.needsUpdate=true;if(r.n){r.g.attributes.normal.array.set(r.n);r.g.attributes.normal.needsUpdate=true;}r.g.boundingBox=r.box?.clone()??null;r.g.boundingSphere=r.sphere?.clone()??null;}}
 try{poser.setPose('stand',0,0);model.updateWorldMatrix(true,true);const inverse=model.matrixWorld.clone().invert();for(const r of saved){const matrix=inverse.clone().multiply(r.mesh.matrixWorld),a=r.g.attributes.position,rest=new Float32Array(a.count*3),active=[];for(let i=0;i<a.count;i++){v.fromBufferAttribute(a,i).applyMatrix4(matrix);rest.set(v.toArray(),i*3);if(['Dormi_body','Navy_belly_spiral','Belly_spiral_rounded_tip'].includes(r.mesh.name)&&(armCurveWeight(v.x,v.y)>0||footWeight(v.x,v.y,v.z)>0))active.push(i);if(r.mesh.name==='Dormi_body'){if(v.x>.50&&v.y<.50&&v.y>.23)palms.push(v.clone());if(v.y<.002&&Math.abs(v.x)>.1&&Math.abs(v.x)<.36)soles[v.x<0?'left':'right'].push(v.clone());}}records.push({...r,rest,active,fromRoot:matrix.clone().invert()});}if(!palms.length||!soles.left.length||!soles.right.length)throw Error('Original curling palm/soles missing');}catch(e){restore();throw e;}
 function setup(f){const lift=Math.max(0,Math.min(1,f.aidLift??0));arms.setRotations({left:new T.Quaternion(),right:new T.Quaternion().setFromAxisAngle(new T.Vector3(1,0,0),A.pushAngle+(A.carryAngle-A.pushAngle)*lift)});for(const side of['left','right']){const p=f.feet[side];feet[side]=new T.Vector3(p.x-f.root.x-(side==='left'?-.21:.21),p.y-f.root.y,p.z-f.root.z);}}
 function deform(x,y,z,out){arms.map(source.set(x,y,z),out);const t=Math.max(0,Math.min(1,(Math.abs(x)-.36)/.04));return out.addScaledVector(feet[x<0?'left':'right'],footWeight(x,y,z)*(1-t*t*(3-2*t)));}
 function apply(f){if(!alive)throw Error('Curling rig released');if(!f?.root||!f?.feet)throw TypeError('Curling support missing');setup(f);for(const r of records){if(!r.active.length)continue;const a=r.g.attributes.position;for(const i of r.active){const k=i*3;deform(r.rest[k],r.rest[k+1],r.rest[k+2],v).applyMatrix4(r.fromRoot);a.setXYZ(i,v.x,v.y,v.z);}a.needsUpdate=true;r.g.computeVertexNormals();r.g.computeBoundingBox();r.g.computeBoundingSphere();}}
 function probe(f,station){if(!alive)throw Error('Curling rig released');setup(f);station.machine.updateWorldMatrix(true,true);const root=station.machine.matrixWorld.clone().multiply(new T.Matrix4().makeTranslation(f.root.x,f.root.y,f.root.z)),grip=station.aid.grip,m=grip.matrixWorld.clone().invert().multiply(root),shape=grip.geometry.parameters;let gap=Infinity,handVertices=0,aidGap=Infinity,aidVertices=0,supportGap=0;
  for(const p of palms){deform(p.x,p.y,p.z,v).applyMatrix4(m);const d=Math.max(Math.abs(v.x)-shape.width/2,Math.abs(v.y)-shape.height/2,Math.abs(v.z)-shape.depth/2);gap=Math.min(gap,d);if(Math.abs(d)<.004)handVertices++;}
  const h=station.heldStone.handle,hm=h.matrixWorld.clone().invert().multiply(station.aid.head.matrixWorld),ha=station.aid.head.geometry.attributes.position,hs=h.geometry.parameters;for(let i=0;i<ha.count;i++){v.fromBufferAttribute(ha,i).applyMatrix4(hm);if(Math.abs(v.x)>hs.width/2+.0001||Math.abs(v.y)>hs.height/2+.0001)continue;const d=-hs.depth/2-v.z;aidGap=Math.min(aidGap,d);if(Math.abs(d)<.001)aidVertices++;}
  const floor=station.ice.matrixWorld.clone().invert().multiply(root),fs=station.ice.geometry.parameters;for(const side of['left','right']){let bottom=Infinity;for(const p of soles[side]){deform(p.x,p.y,p.z,v).applyMatrix4(floor);if(Math.abs(v.x)<=fs.width/2&&Math.abs(v.z)<=fs.depth/2)bottom=Math.min(bottom,v.y-fs.height/2);}supportGap=Math.max(supportGap,Math.abs(bottom));}
  const p=station.heldStone.root.position;return{gap,handVertices,aidGap,aidVertices,supportGap,stone:{x:p.x,z:p.z}};
 }
 return{apply,probe,release({restore:yes=true}={}){if(!alive)return;if(yes)restore();alive=false;},diagnostics:()=>({actorClones:0,newGeometries:0,newMaterials:0,released:!alive})};
}
